Under Assumptions~1--3, there exist constants $C_1, C_2, C_3>0$ such that
\begin{align*}
\mathbb{P}\Big(R(\widehat f, \widehat \beta)&>R(f^*,\beta^*)+\varepsilon 
\Big)\leq C_{1}\mathcal{N}_{\varepsilon}\exp\Big(-\frac{C_3n \varepsilon^2}{(\|\theta^*\|_\infty+\kappa\tau)^4}\Big),
\end{align*}
where $\mathcal{N}_{\varepsilon}=\{1+2(\|\theta^*\|_\infty+\kappa\tau)/\varepsilon\}\exp( C_2\tau^2 \varepsilon^{-2})$.

Under Assumptions~1--3, there exist constants $C_1, C_2, C_3>0$ such that
\begin{align*}
\mathbb{P}\bigg(R(\widehat f, \widehat \beta) &> R_{\text{emp}}(\widehat f) +\varepsilon \bigg)\leq  C_1 \mathcal{N}_{\varepsilon}\exp\Big(-\frac{C_3n \varepsilon^2}{(\|\theta^*\|_\infty+\kappa\tau)^4}\Big),
\end{align*}
where $\mathcal{N}_{\varepsilon}=\{1+2(\|\theta^*\|_\infty+\kappa\tau)/\varepsilon \}\exp( C_2\tau^2 \varepsilon^{-2})$.

Under Assumptions 1-3, let $\{f_1, \dots, f_M\}$ and $\{\beta_1, \dots, \beta_K\}$ be as in Lemma~4. 
There exist a constant $C_1>0$ such that for all $\varepsilon>0$,
\begin{align*}
\mathbb{P}\bigg( 
\mathrm{maximize}_{\substack{f\in \{f_1, \dots, f_M\}\\ \beta\in \{\beta_1, \dots, \beta_K\}}}
\{\widetilde{R}_{\text{emp}}(f,\beta)-\widetilde{R}_{\text{emp}}'(f,\beta)\}>\frac{\varepsilon}{4}
\bigg)\leq 
\mathcal{N}_{\varepsilon} \,\exp\Big(-  \frac{n\varepsilon^2}{128(\|\theta^*\|_\infty+\kappa \tau)^{4}}\Big),
\end{align*}
where $\mathcal{N}_{\varepsilon}=\{1+2(\|\theta^*\|_\infty+\kappa\tau)/\varepsilon\} 
\exp( C_1\tau^2 \varepsilon^{-2})$.

Under Assumptions 1 and 2,
let $\{(x_i, y_i)\}_{i=1}^{n}$ and $\{(x_j, y_j)\}_{j=n+1}^{2n}$ be two independent copies of i.i.d. data, and let $T_x$ be the empirical measure on their union. Let $\widetilde{R}_{\text{emp}}(f,\beta)$ be the modified empirical risk on $\{(x_i, y_i)\}_{i=1}^{n}$, and $\widetilde{R}'_{\text{emp}}(f,\beta)$ on $\{(x_j, y_j)\}_{i=n+1}^{2n}$. Let $c=64(\|\theta^\ast\|_\infty+\tau \kappa)$, and let $\{f_1, \dots, f_M\}$ be the smallest $L^2(T_x)$ $\varepsilon/\sqrt{2}c$-net of $\mathcal{H}_\tau$, and let  $\{\beta_1, \dots, \beta_K\}$ be an $\varepsilon/c$-net of $I_\tau$. Then
\begin{align*}
\begin{split}
\mathbb{P}\bigg(\sup_{\substack{f\in H_\tau\\
\beta\in I_\tau}}\{\widetilde{R}_{\text{emp}}(f,\beta)-\widetilde{R}_{\text{emp}}'(f,\beta)\}>\frac{\varepsilon}{2} \bigg) 
\leq\mathbb{P}\bigg( 
\mathrm{maximize}_{\substack{f\in \{f_1, \dots, f_M\}\\ \beta\in \{\beta_1, \dots, \beta_K\}}}
\{\widetilde{R}_{\text{emp}}(f,\beta)-\widetilde{R}_{\text{emp}}'(f,\beta)\}>\frac{\varepsilon}{4}
\bigg).
\end{split}
\end{align*}

Let Assumption 3 be true, and
Let $M(Z)$ be the size of an $L^2(T_x)$ $\varepsilon$-covering number of $\mathcal{H}_\tau$ with data $Z=\{(x_i, y_i)\}_{i=1}^{n}$.
There exists a $C>0$ independent of $n$, such that
\begin{equation}
\sup_{Z=\{(x_i, y_i)\}_{i=1}^{n}}M(Z)\leq \exp\bigg( \frac{ C\tau^2}{\varepsilon^2}\bigg).
\end{equation}

Let Assumptions 1 and 2 be true, and suppose that $\{f_1, \dots, f_{M}\}$ is an $L^2 (T_{x})$ $\varepsilon$-net of $\mathcal{H}_\tau$ and that $\{\beta_1, \dots, \beta_K\}$ be an $\varepsilon$-net of $I_\tau$. 
Then for any admissible $f$  and $\beta$, let $f_j$ and $\beta_\ell$ be members of the $\varepsilon$-nets so that $\|f-f_j\|_{L^2(T_x)}<\varepsilon$ and 
$|\beta-\beta_\ell|<\varepsilon$. Then
\begin{equation}
\left|\widetilde R_{emp}(f, \beta) - \widetilde R_{emp}(f_j, \beta_l)\right| \leq 8\varepsilon \Big(\|\theta^\ast\|_\infty +\kappa\tau \Big).
\end{equation}
